r = primitives.call(name='observe_rlbench_scene', prompt='change channel minus')
print(r.ok)
out = r.output
if isinstance(out, dict):
    print(list(out.keys()))
    for k in ['descriptions', 'object_pose_evidence']:
        if k in out:
            print(k, str(out[k])[:1200])
else:
    print(str(out)[:1500])
for tn in ['tv_remote', 'target_button_wrap1', 'target_button_wrap2', 'success0', 'success1', 'tv', 'tv_frame', 'waypoint0', 'waypoint1']:
    g = primitives.call(name='ground_rlbench_target', target_name=tn)
    print(tn, g.ok, str(g.output)[:500])

g = primitives.call(name='ground_rlbench_target', target_name='tv_remote')
out = g.output
if isinstance(out, dict):
    print(list(out.keys()))
    for k in out:
        if k not in ('action_schema', 'observation_summary'):
            print(k, str(out[k])[:700])
for tn in ['target_button_wrap1', 'target_button_wrap2', 'success0', 'tv', 'waypoint0', 'waypoint1', 'waypoint2', 'waypoint3']:
    g = primitives.call(name='ground_rlbench_target', target_name=tn)
    o = g.output
    if isinstance(o, dict):
        for k in ['pose', 'pose_world', 'target_pose', 'source', 'target_name', 'candidates', 'selected']:
            if k in o:
                print(tn, k, str(o[k])[:300])

g = primitives.call(name='ground_rlbench_target', target_name='tv_remote')
o = g.output
sel = o.get('selected') if isinstance(o, dict) else None
if isinstance(sel, dict):
    print('selected keys', list(sel.keys()))
    for k in sel:
        if k != 'evidence':
            print(k, str(sel[k])[:300])
    ev = sel.get('evidence')
    if isinstance(ev, dict):
        print('evidence keys', list(ev.keys()))
        for k in ev:
            if k not in ('camera_fields', 'observation_summary', 'action_schema', 'agent_context', 'mask_fields', 'state_fields'):
                print('ev', k, str(ev[k])[:400])
for k in o:
    if k not in ('selected', 'candidates', 'action_schema', 'observation_summary'):
        print('top', k, str(o[k])[:300])

names = ['target_button_wrap0', 'target_button_wrap1', 'target_button_wrap2', 'success0', 'success1', 'tv', 'waypoint0', 'waypoint1', 'waypoint2', 'waypoint3', 'waypoint4', 'waypoint5', 'waypoint6']
poses = {}
for tn in names:
    g = primitives.call(name='ground_rlbench_target', target_name=tn)
    o = g.output if g.ok else None
    pe = o.get('pose_evidence') if isinstance(o, dict) else None
    if isinstance(pe, dict):
        poses[tn] = pe.get('pose_world')
        print(tn, pe.get('source'), [round(x, 4) for x in pe.get('pose_world')] if pe.get('pose_world') else None)
    else:
        print(tn, g.ok, str(o)[:150])
